-- Official-source verified expansion: IDE, terminal, and codebase agents.

insert into public.tools (
 name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,
 korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,korean_tested,verification_level,verification_notes,
 is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at
)
select * from (values
('Amazon Q Developer','IDE·터미널·AWS에서 코드 작성·검토·보안·운영을 지원하는 AI #코딩 #AI에이전트 #AWS #코드리뷰','Amazon Q Developer는 IDE와 CLI에서 저장소를 이해해 여러 파일을 수정하고 명령·테스트를 실행하며, AWS 리소스 질의·문제 진단·보안 스캔과 Java·.NET 현대화를 지원합니다.','https://aws.amazon.com/q/developer/','https://aws.amazon.com/favicon.ico','Freemium','$0','Free 월 50 에이전트 요청 · Pro 월 $19/사용자',array['영구 Free Tier는 월 50개 에이전트 요청과 IDE·CLI를 제공합니다.','Pro는 사용자당 월 $19에 더 높은 요청 한도와 관리자·IP 보상 기능을 제공합니다.','Pro의 변환 할당량을 넘는 Java 업그레이드는 제출 코드 한 줄당 $0.003입니다.'],'USD','https://aws.amazon.com/q/developer/pricing/',now(),'Full Support',true,true,false,false,false,'official_sources','AWS 공식 제품·가격·문서를 확인했습니다. 실제 저장소 작업과 한국어 응답은 직접 테스트하지 않았습니다.',false,false,null,'Native','specialized',array['IDE·CLI 코딩 에이전트','AWS 질의·진단','코드 리뷰·보안 검사'],array['다중 파일 수정','명령·테스트 실행','Java·.NET 현대화'],array['영구 무료 개발자 플랜','AWS 개발·운영 문맥 통합','IDE와 터미널 지원'],array['AWS를 사용하는 개발자','레거시 앱 현대화와 보안 검사가 필요한 팀'],array['무료 IDE 사용에는 Builder ID 조건이 있습니다.','AWS 리소스 작업은 별도 서비스 비용이 발생할 수 있습니다.','에이전트 명령과 코드 변경은 검토가 필요합니다.'],array['https://aws.amazon.com/q/developer/pricing/','https://aws.amazon.com/q/developer/build/'],now(),now()),
('Gemini Code Assist','IDE와 터미널에서 대규모 코드 문맥을 이해하고 생성·수정하는 Google AI #코딩 #AI에이전트 #Gemini #코드완성','Gemini Code Assist는 VS Code·JetBrains와 Gemini CLI에서 코드 완성, 채팅, 여러 파일 편집과 명령 실행을 지원하며 기업 코드를 반영한 맞춤화·관찰성과 Google Cloud 개발 기능을 제공합니다.','https://codeassist.google/','https://www.google.com/favicon.ico','Freemium','$0','개인 무료 · Standard 연간 월 $19/사용자',array['개인용 무료 버전은 별도 일일·분당 요청 한도 내에서 이용할 수 있습니다.','Standard는 연간 약정 사용자당 월 $19 또는 월간 $22.80입니다.','Enterprise는 연간 월 $45 또는 월간 $54이며 30일 조직 체험을 제공합니다.'],'USD','https://codeassist.google/products/business',now(),'Full Support',true,true,false,false,false,'official_sources','Google 공식 제품·가격·할당량 문서를 확인했습니다. 실제 코드 변경과 한국어 품질은 직접 테스트하지 않았습니다.',false,false,null,'Native','specialized',array['코드 완성·채팅','에이전트 다중 파일 수정','Gemini CLI'],array['1M 토큰 코드 문맥','기업 코드 맞춤화','Google Cloud 통합'],array['개인 개발자 무료 사용','IDE·CLI와 Cloud 기능 연결','기업 데이터 관리 기능'],array['Google 생태계 개발자','대형 저장소 문맥이 필요한 기업 개발팀'],array['개인 무료 제품은 2026년 서비스 전환 공지를 확인해야 합니다.','한 프롬프트가 여러 모델 요청을 소비할 수 있습니다.','에이전트 모드 일부 기능은 Preview입니다.'],array['https://codeassist.google/products/business','https://docs.cloud.google.com/gemini/docs/quotas'],now(),now()),
('Sourcegraph','대규모 코드베이스를 검색·이해하고 에이전트 변경에 문맥을 제공하는 플랫폼 #코드검색 #코드분석 #AI에이전트 #개발','Sourcegraph는 여러 저장소의 코드 검색과 코드 그래프를 바탕으로 자연어 Deep Search, 대규모 Batch Changes·현대화와 외부 코딩 에이전트용 MCP·API 문맥을 제공합니다.','https://sourcegraph.com/','https://sourcegraph.com/favicon.ico','Paid',null,'기업용 견적 · 공개 코드 검색 무료',array['공개 저장소 Code Search는 무료로 사용할 수 있습니다.','기업용 Code Search·Deep Search·Batch Changes와 관리 기능은 영업 견적이 필요합니다.','구축 방식과 사용자·코드 규모에 따라 계약 조건이 달라집니다.'],'USD','https://sourcegraph.com/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격 페이지를 확인했습니다. 기업 견적, 검색 품질과 API는 직접 테스트하지 않았습니다.',false,true,'https://sourcegraph.com/docs/api','Augmented','specialized',array['대규모 코드 검색','에이전트형 자연어 검색','코드 그래프 문맥'],array['Batch Changes','코드 현대화','MCP·API·CLI'],array['다중 저장소를 한 번에 이해','코딩 에이전트에 구조적 문맥 제공','대규모 변경과 분석 지원'],array['대형 코드베이스를 운영하는 기업','여러 저장소를 검색·현대화하는 플랫폼 팀'],array['기업 기능의 공개 정액 가격이 없습니다.','저장소 인덱싱과 권한 동기화 설정이 필요합니다.','AI 검색 결과와 대규모 변경은 사람 검토가 필요합니다.'],array['https://sourcegraph.com/pricing','https://sourcegraph.com/docs'],now(),now()),
('Cline','사용자가 고른 모델로 파일·터미널·브라우저를 조작하는 오픈소스 코딩 에이전트 #코딩 #오픈소스 #AI에이전트 #BYOK','Cline은 VS Code와 CLI에서 계획을 세워 파일을 읽고 수정하며 명령과 브라우저·MCP 도구를 실행하는 오픈소스 코딩 에이전트로, 다양한 모델 제공자와 사용자 API 키를 지원합니다.','https://cline.bot/','https://cline.bot/favicon.ico','Freemium','$0','개인용 오픈소스 무료 · 모델 추론비 별도',array['개인용 VS Code 확장과 CLI는 구독료 없이 무료입니다.','Cline 제공 추론 크레딧 또는 사용자가 연결한 모델 API 사용료만 발생합니다.','기업용 SSO·RBAC·중앙 관리·감사 기능은 맞춤 견적입니다.'],'USD','https://cline.bot/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격 자료를 확인했습니다. 설치, 코드 변경과 모델 연결은 직접 테스트하지 않았습니다.',false,false,null,'Augmented','specialized',array['파일·터미널 코딩 에이전트','계획·실행 승인','다중 모델 BYOK'],array['브라우저 조작','MCP 마켓플레이스','VS Code·CLI'],array['오픈소스 무료 클라이언트','모델 제공자 선택과 비용 통제','실행 단계별 사용자 승인'],array['모델과 비용을 직접 선택하는 개발자','확장 가능한 로컬 코딩 에이전트가 필요한 사용자'],array['클라이언트는 무료지만 모델 API 비용이 발생합니다.','명령 실행과 파일 변경 권한을 신중히 승인해야 합니다.','품질·비용·개인정보 정책은 선택한 모델 제공자에 따라 다릅니다.'],array['https://cline.bot/pricing'],now(),now()),
('Continue','IDE·CLI용 맞춤 AI 코딩 에이전트를 구성하는 오픈소스 플랫폼 #코딩 #오픈소스 #AI에이전트 #BYOK','Continue는 VS Code·JetBrains·CLI에서 채팅, 자동완성, 편집과 Agent 모드를 제공하고 YAML로 모델·규칙·MCP 도구를 조합해 개인·팀용 코딩 에이전트를 구성합니다.','https://www.continue.dev/','https://www.continue.dev/favicon.ico','Freemium','$0','오픈소스 확장 무료 · 연결 모델 비용 별도',array['IDE 확장과 로컬 구성은 오픈소스로 무료 사용할 수 있습니다.','로컬 모델을 사용하면 외부 모델 API 비용 없이 구성할 수 있습니다.','클라우드 모델·호스팅·팀 관리 비용은 선택한 제공자와 계약에 따라 달라집니다.'],'USD','https://www.continue.dev/',now(),'None',true,true,false,false,false,'official_sources','공식 제품·설치·모델 구성 문서를 확인했습니다. 설치와 에이전트 실행은 직접 테스트하지 않았습니다.',false,false,null,'Augmented','specialized',array['IDE·CLI 코딩 에이전트','채팅·편집·자동완성','모델·규칙·도구 구성'],array['MCP','로컬 모델','팀 구성 공유'],array['오픈소스와 다양한 모델 선택','로컬·클라우드 혼합 구성','재사용 가능한 코딩 에이전트 설정'],array['코딩 도우미 구성을 직접 통제하는 개발자','팀별 개발 규칙과 모델을 표준화하는 조직'],array['도구 자체와 모델 추론 비용을 구분해야 합니다.','로컬 구성은 YAML과 모델 서버 설정이 필요합니다.','API 키를 설정 파일에 직접 저장하지 않아야 합니다.'],array['https://docs.continue.dev/','https://docs.continue.dev/customize/model-providers/overview'],now(),now()),
('Aider','Git 저장소에서 여러 파일을 수정하고 커밋하는 터미널 기반 AI 페어 프로그래머 #코딩 #오픈소스 #터미널 #BYOK','Aider는 터미널에서 저장소 지도를 이용해 기존 코드베이스를 이해하고 여러 파일을 편집·커밋하며 테스트·린트를 실행하는 오픈소스 AI 페어 프로그래밍 도구입니다.','https://aider.chat/','https://aider.chat/assets/icons/favicon-32x32.png','Freemium','$0','오픈소스 무료 · 연결한 모델 API 비용 별도',array['Aider 프로그램은 무료 오픈소스입니다.','OpenAI·Anthropic·Gemini·OpenRouter·로컬 모델 등 연결한 제공자의 추론비가 발생합니다.','로컬 모델을 직접 실행하는 경우 별도 클라우드 API 비용 없이 사용할 수 있습니다.'],'USD','https://aider.chat/docs/',now(),'None',true,true,false,false,false,'official_sources','공식 제품·문서를 확인했습니다. 설치, 모델 연결과 코드 편집은 직접 테스트하지 않았습니다.',false,false,null,'Augmented','specialized',array['터미널 코드 편집','저장소 지도','Git 자동 커밋'],array['테스트·린트 실행','다중 모델','음성 입력'],array['가벼운 터미널 중심 워크플로','광범위한 모델 제공자 지원','Git 변경 추적과 되돌리기'],array['터미널과 Git에 익숙한 개발자','오픈소스 AI 페어 프로그래밍을 원하는 사용자'],array['모델 API 키와 비용을 사용자가 관리해야 합니다.','자동 커밋과 명령 실행 결과를 검토해야 합니다.','대형 저장소는 모델 문맥과 토큰 비용이 증가할 수 있습니다.'],array['https://aider.chat/','https://aider.chat/docs/'],now(),now()),
('Warp','현대적 터미널에 명령 실행·코드 작성·클라우드 에이전트를 결합한 AI #터미널 #코딩 #AI에이전트 #개발','Warp는 명령 블록과 팀 지식 공유를 제공하는 터미널에 자연어 명령 생성, 코드베이스 작업을 수행하는 Warp Agent와 백그라운드 클라우드 에이전트를 통합합니다.','https://www.warp.dev/','https://www.warp.dev/favicon.ico','Freemium','$0','Free 제한 에이전트 · Build 월 $20부터',array['Free는 기본 터미널과 BYO inference, 제한된 클라우드 에이전트를 제공합니다.','Build는 월 $20부터 1,500크레딧과 전체 Warp Agent 접근을 제공합니다.','사용량이 포함 크레딧을 넘으면 선택한 플랜의 종량 조건이 적용됩니다.'],'USD','https://www.warp.dev/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격 자료를 확인했습니다. 설치, 명령 실행과 클라우드 에이전트는 직접 테스트하지 않았습니다.',false,false,null,'Native','specialized',array['AI 터미널','코딩·명령 실행 에이전트','클라우드 백그라운드 작업'],array['팀 지식 Warp Drive','BYO inference','협업'],array['터미널과 에이전트 통합','무료 기본 터미널','로컬·클라우드 작업 선택'],array['터미널 중심으로 개발하는 사용자','장시간 작업을 클라우드에 맡기는 개발팀'],array['에이전트 사용량은 크레딧 기반입니다.','명령 실행 전에 대상과 영향을 확인해야 합니다.','일부 클라우드·협업 기능은 유료 플랜이 필요합니다.'],array['https://www.warp.dev/pricing'],now(),now())
) as seed(name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,korean_tested,verification_level,verification_notes,is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at)
where not exists(select 1 from public.tools where lower(tools.url)=lower(seed.url));

with assignments(tool_url,category_slug) as (values
('https://aws.amazon.com/q/developer/','development'),('https://codeassist.google/','development'),
('https://sourcegraph.com/','development'),('https://sourcegraph.com/','search-data'),
('https://cline.bot/','development'),('https://www.continue.dev/','development'),
('https://aider.chat/','development'),('https://www.warp.dev/','development'),('https://www.warp.dev/','productivity')
)
insert into public.tool_categories(tool_id,category_id)
select tools.id,categories.id from assignments
join public.tools on lower(tools.url)=lower(assignments.tool_url)
join public.categories on lower(categories.slug)=lower(assignments.category_slug)
on conflict(tool_id,category_id) do nothing;
